, refs) => {\\n    // 定义一个空数组，用于存储最终的结果\\n    const result = [];\\n\\n    // 定义一个对象，用于存储地区对象的引用，以便在构建层次结构时能够快速查找父地区\\n    const regionsMap = {};\\n\\n    // 遍历原始数据\\n    data.forEach(item => {\\n        // 创建一个地区对象，包含 id、label、num 和 children 字段\\n        const region = {\\n            id: item.id,\\n            label: item.label,\\n            num: item.num,\\n            children: []\\n        };\\n\\n        // 将当前地区对象添加到引用对象中，以地区的 id 作为键\\n        regionsMap[item.id] = region;\\n\\n        // 如果当前地区有父地区，将其添加到父地区的 children 数组中\\n        if (item.parent_id) {\\n            const parentRegion = regionsMap[item.parent_id];\\n            if (parentRegion) {\\n                parentRegion.children.push(region);\\n            }\\n        } else {\\n            // 如果当前地区是顶级地区，则直接将其添加到最终结果数组中\\n            result.push(region);\\n        }\\n    });\\n\\n    return result;\\n};\",\"dataHeader\":\"\",\"dataQuery\":\"\",\"stylesFormatter\":\"\",\"component\":{\"width\":122,\"height\":24,\"name\":\"advancedSelection\",\"prop\":\"advancedSelection\"},\"option\":{\"showHeader\":true,\"columnShow\":true,\"columnViews\":true,\"headerTextAlign\":\"center\",\"bodyTextAlign\":\"center\",\"align\":\"center\",\"headerAlign\":\"center\",\"header\":false,\"scrollSpeed\":1,\"count\":4,\"index\":false,\"column\":[{\"id\":1,\"label\":\"名称\",\"prop\":\"label\",\"width\":140,\"hide\":false,\"$index\":0},{\"id\":2,\"label\":\"编号\",\"prop\":\"num\",\"width\":140,\"hide\":false,\"$index\":1}],\"menuForm\":{\"dynamic\":[{\"name\":\"\",\"link\":\"\",\"param\":\"\"}]},\"headerFontSize\":14,\"borderSize\":1,\"border\":false,\"bodyFontSize\":12,\"dialogWidth\":30,\"color\":\"#000000\",\"backgroundColor\":\"#fff\",\"fontSize\":12,\"borderColor\":\"#808080\",\"imageFlag\":\"qh\"},\"left\":1216.62,\"top\":12.96,\"index\":\"93ab35c7-cfb9-4b6c-8a98-c70db1e5838d\",\"zIndex\":2,\"child\":{},\"sql\":\"ox1q5f//+zTNZ9UEpEqGJubjl2J6LB5nJWYhvkryPRu8hQomq4QAXqjLgKjYD+ud0zRC1wJ5cxLbKwis4r7waw==\"},{\"name\":\"数据表